855→+  constructor(private readonly configService: ConfigService) {
856→+    this.delegatedRoutingUrl = this.configService.get<string>(
857→+      'DELEGATED_ROUTING_URL',
858→+      'https://delegated-ipfs.dev'
859→+    );
860→+  }
861→+
862→+  /**
863→+   * Publish an IPNS record via the delegated routing PUT API with exponential backoff retry.
864→+   * Throws HttpException (BAD_GATEWAY) on persistent failures.
865→+   */
866→+  async publish(ipnsName: string, recordBytes: Uint8Array): Promise<void> {
867→+    const url = `${this.delegatedRoutingUrl}/routing/v1/ipns/${encodeURIComponent(ipnsName)}`;
868→+
869→+    let lastError: Error | null = null;
870→+
871→+    for (let attempt = 0; attempt < this.maxRetries; attempt++) {
872→+      try {
873→+        const { ok, status, retryAfter, errorText } = await this.fetchWithTimeout(
874→+          url,
875→+          {
876→+            method: 'PUT',
877→+            headers: {
878→+              'Content-Type': 'application/vnd.ipfs.ipns-record',
879→+            },
880→+            body: recordBytes as unknown as BodyInit,
881→+          },
882→+          async (response) => ({
883→+            ok: response.ok,
884→+            status: response.status,
885→+            retryAfter: response.headers.get('Retry-After'),
886→+            errorText: !response.ok && response.status !== 429 ? await response.text() : '',
887→+          })
888→+        );
889→+
890→+        if (ok) {
891→+          this.logger.log(`IPNS record published successfully for ${ipnsName}`);
892→+          return;
893→+        }
894→+
895→+        // Handle rate limiting
896→+        if (status === 429) {
897→+          if (attempt < this.maxRetries - 1) {
898→+            const delayMs = this.getRetryDelayMs(retryAfter, attempt);
