882→+          async (response) => ({
883→+            ok: response.ok,
884→+            status: response.status,
885→+            retryAfter: response.headers.get('Retry-After'),
886→+            errorText: !response.ok && response.status !== 429 ? await response.text() : '',
887→+          })
888→+        );
889→+
