1046→+  private async fetchWithTimeout<T>(
1047→+    url: string,
1048→+    init: RequestInit,
1049→+    consume: (response: Response) => Promise<T>
1050→+  ): Promise<T> {
1051→+    const controller = new AbortController();
1052→+    const timeout = setTimeout(() => controller.abort(), this.requestTimeoutMs);
1053→+    try {
1054→+      const response = await fetch(url, { ...init, signal: controller.signal });
1055→+      return await consume(response);
1056→+    } finally {
1057→+      clearTimeout(timeout);
1058→+    }
1059→+  }
1060→+
1061→+  private getRetryDelayMs(retryAfter: string | null, attempt: number): number {
1062→+    const fallback = this.baseDelayMs * Math.pow(2, attempt);
1063→+    if (!retryAfter) return Math.min(fallback, this.maxRetryDelayMs);
1064→+
1065→+    const seconds = Number(retryAfter);
1066→+    if (Number.isFinite(seconds) && seconds >= 0) {
1067→+      return Math.min(seconds * 1000, this.maxRetryDelayMs);
1068→+    }
1069→+
1070→+    const retryAt = Date.parse(retryAfter);
1071→+    if (!Number.isNaN(retryAt)) {
1072→+      return Math.min(Math.max(0, retryAt - Date.now()), this.maxRetryDelayMs);
1073→+    }
1074→+
1075→+    return Math.min(fallback, this.maxRetryDelayMs);
1076→+  }
