 1→import { Module, Global, OnModuleDestroy, Inject, Logger } from '@nestjs/common';
 2→import { ConfigService } from '@nestjs/config';
 3→import Redis from 'ioredis';
 4→
 5→export const REDIS_CLIENT = Symbol('REDIS_CLIENT');
 6→
 7→@Global()
 8→@Module({
 9→  providers: [
10→    {
11→      provide: REDIS_CLIENT,
12→      useFactory: (config: ConfigService): Redis => {
13→        return new Redis({
14→          host: config.get('REDIS_HOST', 'localhost'),
15→          port: config.get<number>('REDIS_PORT', 6379),
16→          password: config.get('REDIS_PASSWORD', undefined),
17→          lazyConnect: true,
18→        });
19→      },
20→      inject: [ConfigService],
21→    },
22→  ],
23→  exports: [REDIS_CLIENT],
24→})
25→export class RedisModule implements OnModuleDestroy {
26→  private readonly logger = new Logger(RedisModule.name);
27→
28→  constructor(@Inject(REDIS_CLIENT) private readonly redis: Redis) {}
29→
30→  async onModuleDestroy(): Promise<void> {
31→    try {
32→      await this.redis.quit();
33→    } catch {
34→      this.logger.warn('Redis disconnect failed during shutdown');
35→    }
36→  }
37→}
