 1→import { useState, useCallback } from 'react';
 2→
 3→export type DialogState<T> = {
 4→  open: boolean;
 5→  item: T | null;
 6→};
 7→
 8→const CLOSED_STATE = { open: false, item: null } as const;
 9→
10→/**
11→ * Manage open/close state for a dialog that operates on an item.
12→ *
13→ * Returns a tuple of [state, open, close] where:
14→ * - state.open: whether the dialog is visible
15→ * - state.item: the item being operated on (null when closed)
16→ * - open(item): open the dialog for a given item
17→ * - close(): close the dialog and clear the item
18→ */
19→export function useDialogState<T>(): [DialogState<T>, (item: T) => void, () => void] {
20→  const [state, setState] = useState<DialogState<T>>(CLOSED_STATE);
21→
22→  const open = useCallback((item: T) => {
23→    setState({ open: true, item });
24→  }, []);
25→
26→  const close = useCallback(() => {
27→    setState(CLOSED_STATE);
28→  }, []);
29→
30→  return [state, open, close];
31→}
