  4→@Injectable()
  5→export class DelegatedRoutingClient {
  6→  private readonly logger = new Logger(DelegatedRoutingClient.name);
  7→  private readonly delegatedRoutingUrl: string;
  8→  private readonly maxRetries = 3;
  9→  private readonly baseDelayMs = 1000;
 10→  private readonly maxRetryDelayMs = 30_000;
 11→  private readonly requestTimeoutMs = 10_000;
 12→
 13→  constructor(private readonly configService: ConfigService) {
 14→    this.delegatedRoutingUrl = this.configService.get<string>(
 15→      'DELEGATED_ROUTING_URL',
 16→      'https://delegated-ipfs.dev'
 17→    );
 18→  }
 19→
 20→  /**
 21→   * Publish an IPNS record via the delegated routing PUT API with exponential backoff retry.
 22→   * Throws HttpException (BAD_GATEWAY) on persistent failures.
 23→   */
 24→  async publish(ipnsName: string, recordBytes: Uint8Array): Promise<void> {
 25→    const url = `${this.delegatedRoutingUrl}/routing/v1/ipns/${encodeURIComponent(ipnsName)}`;
 26→
 27→    let lastError: Error | null = null;
 28→
 29→    for (let attempt = 0; attempt < this.maxRetries; attempt++) {
 30→      try {
 31→        const { ok, status, retryAfter, errorText } = await this.fetchWithTimeout(
 32→          url,
 33→          {
 34→            method: 'PUT',
 35→            headers: {
 36→              'Content-Type': 'application/vnd.ipfs.ipns-record',
 37→            },
 38→            body: recordBytes as unknown as BodyInit,
 39→          },
 40→          async (response) => ({
 41→            ok: response.ok,
 42→            status: response.status,
 43→            retryAfter: response.headers.get('Retry-After'),
 44→            errorText: !response.ok && response.status !== 429 ? await response.text() : '',
 45→          })
 46→        );
 47→
 48→        if (ok) {
 49→          this.logger.log(`IPNS record published successfully for ${ipnsName}`);
 50→          return;
 51→        }
 52→
 53→        // Handle rate limiting
 54→        if (status === 429) {
 55→          if (attempt < this.maxRetries - 1) {
 56→            const delayMs = this.getRetryDelayMs(retryAfter, attempt);
 57→
 58→            this.logger.warn(`Rate limited on IPNS publish, retrying in ${delayMs}ms`);
 59→            await this.delay(delayMs);
 60→          }
 61→          continue;
 62→        }
 63→
 64→        // Non-retryable HTTP error
 65→        // [SECURITY: MEDIUM-11] Log full error details but don't expose to client
 66→        this.logger.error(`Delegated routing returned ${status} for ${ipnsName}: ${errorText}`);
 67→        throw new Error(`Delegated routing returned ${status}`);
 68→      } catch (error) {
 69→        lastError = error instanceof Error ? error : new Error(String(error));
 70→
 71→        // Only retry on network errors, not on HTTP errors
 72→        if (
 73→          lastError.message.includes('Delegated routing returned') &&
 74→          !lastError.message.includes('429')
 75→        ) {
 76→          // [SECURITY: MEDIUM-11] Generic error message to avoid leaking internal details
 77→          throw new HttpException(
 78→            'Failed to publish IPNS record to routing network',
 79→            HttpStatus.BAD_GATEWAY
 80→          );
 81→        }
 82→
 83→        // Exponential backoff for network errors
 84→        if (attempt < this.maxRetries - 1) {
 85→          const delayMs = this.baseDelayMs * Math.pow(2, attempt);
 86→          this.logger.warn(
 87→            `IPNS publish attempt ${attempt + 1} failed, retrying in ${delayMs}ms: ${lastError.message}`
 88→          );
 89→          await this.delay(delayMs);
 90→        }
 91→      }
 92→    }
 93→
 94→    // [SECURITY: MEDIUM-11] Log full error, return generic message
 95→    this.logger.error(
 96→      `Failed to publish IPNS record after ${this.maxRetries} attempts: ${lastError?.message}`
 97→    );
 98→    throw new HttpException(
 99→      'Failed to publish IPNS record to routing network after multiple attempts',
100→      HttpStatus.BAD_GATEWAY
101→    );
102→  }
103→
104→  /**
105→   * Resolve an IPNS name via the delegated routing GET API with retries.
106→   * Returns the raw record bytes, or null if the IPNS name is not found (404).
107→   * Throws HttpException (BAD_GATEWAY) on routing failures.
108→   */
109→  async resolve(ipnsName: string): Promise<Uint8Array | null> {
110→    const url = `${this.delegatedRoutingUrl}/routing/v1/ipns/${encodeURIComponent(ipnsName)}`;
111→
112→    let lastError: Error | null = null;
113→
114→    for (let attempt = 0; attempt < this.maxRetries; attempt++) {
115→      try {
116→        const { ok, status, retryAfter, data, errorText } = await this.fetchWithTimeout(
117→          url,
118→          {
119→            method: 'GET',
120→            headers: {
121→              Accept: 'application/vnd.ipfs.ipns-record',
122→            },
123→          },
124→          async (response) => ({
125→            ok: response.ok,
126→            status: response.status,
127→            retryAfter: response.headers.get('Retry-After'),
128→            data: response.ok ? new Uint8Array(await response.arrayBuffer()) : null,
129→            errorText:
130→              !response.ok && response.status !== 404 && response.status !== 429
131→                ? await response.text()
132→                : '',
133→          })
134→        );
135→
136→        // 404 means IPNS name not found - not an error
137→        if (status === 404) {
138→          this.logger.debug(`IPNS name not found: ${ipnsName}`);
139→          return null;
140→        }
141→
142→        if (ok) {
143→          return data;
144→        }
145→
146→        // Handle rate limiting
147→        if (status === 429) {
148→          if (attempt < this.maxRetries - 1) {
149→            const delayMs = this.getRetryDelayMs(retryAfter, attempt);
150→
151→            this.logger.warn(`Rate limited on IPNS resolve, retrying in ${delayMs}ms`);
152→            await this.delay(delayMs);
153→          }
154→          continue;
155→        }
156→
157→        // Non-retryable error
158→        // [SECURITY: MEDIUM-11] Log full error details but don't expose to client
159→        this.logger.error(
160→          `Delegated routing resolution returned ${status} for ${ipnsName}: ${errorText}`
161→        );
162→        throw new Error(`Delegated routing returned ${status}`);
163→      } catch (error) {
164→        // Re-throw HttpException immediately (e.g., parsing errors) - don't retry
165→        if (error instanceof HttpException) {
166→          throw error;
167→        }
168→
169→        lastError = error instanceof Error ? error : new Error(String(error));
170→
171→        // Only retry on network errors, not on HTTP errors
172→        if (
173→          lastError.message.includes('Delegated routing returned') &&
174→          !lastError.message.includes('429')
175→        ) {
176→          // [SECURITY: MEDIUM-11] Generic error message to avoid leaking internal details
177→          throw new HttpException(
178→            'Failed to resolve IPNS name from routing network',
179→            HttpStatus.BAD_GATEWAY
180→          );
181→        }
182→
183→        // Exponential backoff for network errors
184→        if (attempt < this.maxRetries - 1) {
185→          const delayMs = this.baseDelayMs * Math.pow(2, attempt);
186→          this.logger.warn(
187→            `IPNS resolve attempt ${attempt + 1} failed, retrying in ${delayMs}ms: ${lastError.message}`
188→          );
189→          await this.delay(delayMs);
190→        }
191→      }
192→    }
193→
194→    // [SECURITY: MEDIUM-11] Log full error, return generic message
195→    this.logger.error(
196→      `Failed to resolve IPNS name after ${this.maxRetries} attempts: ${lastError?.message}`
197→    );
198→    throw new HttpException(
199→      'Failed to resolve IPNS name from routing network after multiple attempts',
200→      HttpStatus.BAD_GATEWAY
201→    );
202→  }
203→
204→  private async fetchWithTimeout<T>(
205→    url: string,
206→    init: RequestInit,
207→    consume: (response: Response) => Promise<T>
208→  ): Promise<T> {
209→    const controller = new AbortController();
210→    const timeout = setTimeout(() => controller.abort(), this.requestTimeoutMs);
211→    try {
212→      const response = await fetch(url, { ...init, signal: controller.signal });
213→      return await consume(response);
214→    } finally {
215→      clearTimeout(timeout);
216→    }
217→  }
218→
219→  private getRetryDelayMs(retryAfter: string | null, attempt: number): number {
220→    const fallback = this.baseDelayMs * Math.pow(2, attempt);
221→    if (!retryAfter) return Math.min(fallback, this.maxRetryDelayMs);
222→
223→    const seconds = Number(retryAfter);
224→    if (Number.isFinite(seconds) && seconds >= 0) {
225→      return Math.min(seconds * 1000, this.maxRetryDelayMs);
226→    }
227→
228→    const retryAt = Date.parse(retryAfter);
229→    if (!Number.isNaN(retryAt)) {
230→      return Math.min(Math.max(0, retryAt - Date.now()), this.maxRetryDelayMs);
231→    }
232→
233→    return Math.min(fallback, this.maxRetryDelayMs);
234→  }
235→
236→  private delay(ms: number): Promise<void> {
237→    return new Promise((resolve) => setTimeout(resolve, ms));
238→  }
239→}
